posts.body:
You can also make a plugin that move the weapon sprite 1 layers above the main sprite.
For example if the weapon type is 12 or 13.
You can edit the code or someone just make a full plugin with parameters.
JavaScript:
(function (alias) {
  Sprite_Actor.prototype.setupWeaponAnimation = function () {
    if ([12, 13].includes(this._actor.weaponImageId())) {
      this.addChildAt(this._weaponSprite, this.getChildIndex(this._mainSprite)+1);
    }
    alias.apply(this, arguments);
  };
})(Sprite_Actor.prototype.setupWeaponAnimation);
